arguments.command:
python3 -c "
import subprocess
result = subprocess.run(['pip', 'list'], capture_output=True, text=True)
packages = result.stdout
for pkg in ['sklearn', 'xgboost', 'lightgbm', 'catboost', 'transformers', 'torch', 'tensorflow', 'nltk', 'spacy', 'regex', 'sentence_transformers']:
    if pkg.lower() in packages.lower():
        print(f'{pkg}: FOUND')
    else:
        print(f'{pkg}: NOT FOUND')
"

